    image: "{\"_id\":\"676af7e306f2811e8303622c\",\"extention\":\".webp\",\"filename\":\"brilliance-contemporary-nihonga-painting-by-chen-yiching-1-550x739\",\"is_folder\":false,\"is_delete\":false,\"file_info\":\"{'extention': '.webp', 'filename': 'brilliance-contemporary-nihonga-painting-by-chen-yiching-1-550x739', 'size': 57626, 'path': 'uploads\\\\\\\\2024\\\\\\\\12\\\\\\\\25\\\\\\\\brilliance-contemporary-nihonga-painting-by-chen-yiching-1-550x739.webp'}\",\"url\":\"/uploads/2024/12/25/brilliance-contemporary-nihonga-painting-by-chen-yiching-1-550x739.webp\",\"media_id\":\"\"}",
